// Turn {objectType, runId, config} from the orchestrator into an explicit,
// object-specific job spec. Everything downstream reads from here.
const inp = $input.first().json || {};
const cfg = inp.config || {};
const objectType = String(inp.objectType || 'contacts').toLowerCase();

if (!['contacts', 'companies', 'deals'].includes(objectType)) {
  throw new Error(`Unsupported objectType "${objectType}". Expected contacts | companies | deals.`);
}

// HubSpot names the "last modified" property differently per object.
const LASTMOD = { contacts: 'lastmodifieddate', companies: 'hs_lastmodifieddate', deals: 'hs_lastmodifieddate' };

const READ = {
  contacts: ['email','firstname','lastname','phone','mobilephone','company','jobtitle','website',
             'city','state','country','zip','lifecyclestage','hs_object_id','createdate',
             'lastmodifieddate','hs_email_domain','hs_merged_object_ids',
             'hygiene_score','hygiene_flags','hygiene_last_run','dedupe_status'],
  companies: ['name','domain','website','phone','city','state','country','zip','industry',
              'numberofemployees','lifecyclestage','hs_object_id','createdate',
              'hs_lastmodifieddate','hs_merged_object_ids',
              'hygiene_score','hygiene_flags','hygiene_last_run','dedupe_status'],
  deals: ['dealname','amount','closedate','dealstage','pipeline','hs_object_id','createdate',
          'hs_lastmodifieddate','hs_merged_object_ids',
          'hygiene_score','hygiene_flags','hygiene_last_run','dedupe_status'],
};

// Completeness weights — tune these per client; they must add up to 100.
const WEIGHTS = {
  contacts:  { email:25, firstname:10, lastname:10, phone:15, company:10, jobtitle:10, country:10, lifecyclestage:10 },
  companies: { name:20, domain:25, phone:10, city:10, country:10, industry:10, numberofemployees:8, website:7 },
  deals:     { dealname:25, amount:25, closedate:25, dealstage:25 },
};

const lookbackH = Number(cfg.hygieneLookbackHours ?? 26);
const sinceMs = Date.now() - lookbackH * 3600 * 1000;

return [{ json: {
  runId: inp.runId || `manual-${Date.now()}`,
  objectType,
  lastModProp: LASTMOD[objectType],
  readProps: READ[objectType],
  weights: WEIGHTS[objectType],
  mode: String(cfg.hygieneMode || 'delta').toLowerCase() === 'full' ? 'full' : 'delta',
  sinceMs,
  config: {
    pageSize:          Math.min(Number(cfg.pageSize ?? 100), 100),
    maxPagesPerRun:    Number(cfg.maxPagesPerRun ?? 200),
    apiThrottleMs:     Number(cfg.apiThrottleMs ?? 250),
    defaultCountry:    String(cfg.defaultCountry || 'US').toUpperCase(),
    dryRun:            cfg.dryRun !== false,
    writeHygieneProps: cfg.writeHygieneProps !== false,
    slackChannel:      cfg.slackChannel || '#crm-hygiene',
  },
  stats: { scanned:0, recordsUpdated:0, fieldsChanged:0, recordsFlagged:0,
           writeErrors:0, pages:0, byFix:{}, byFlag:{} },
} }];

// Runs once before the first page and again on every loop-back.
// It carries the running stats and builds the HubSpot Search body.
const j = $input.first().json;
const spec = $('⚙️ Resolve Job Config').first().json;

const after  = j.nextAfter || null;
const pageNo = Number(j.pageNo || 0) + 1;
const stats  = j.stats || spec.stats;

const body = {
  limit: spec.config.pageSize,
  properties: spec.readProps,
  sorts: [{ propertyName: spec.lastModProp, direction: 'ASCENDING' }],
  filterGroups: spec.mode === 'delta'
    ? [{ filters: [{ propertyName: spec.lastModProp, operator: 'GTE', value: String(spec.sinceMs) }] }]
    : [],
};
if (after) body.after = String(after);

return [{ json: { ...spec, pageNo, after, stats, searchBody: body } }];

// A page fetch that still failed after 3 retries ends the scan cleanly instead
// of killing the whole run — the orchestrator digest reports what was done.
const e = $input.first().json || {};
const spec = $('🔁 Next Page Cursor').first().json;
const msg = String(e.error?.message || e.message || JSON.stringify(e)).slice(0, 500);
const stats = { ...(spec.stats || {}), fetchError: msg, pages: Number(spec.pageNo || 0) - 1 };
return [{ json: { ...spec, stats, hasMore: false, aborted: true, abortReason: msg } }];

