  'spa','s.p.a.','pty','plc','p.l.c.','llp','l.l.p.','lp','pvt','pvt.','private','kk','k.k.',
  'kg','ug','doo','d.o.o.','sp','zoo','z.o.o.','pte','sdn','bhd','cv','ou','sro','s.r.o.']);

const ACRONYMS = new Set(['CEO','CTO','CFO','COO','CMO','CIO','CISO','CRO','CPO','VP','SVP','EVP',
  'AVP','IT','HR','PR','QA','UX','UI','SEO','SEM','SMB','B2B','B2C','SaaS','AI','ML','R&D','PM',
  'BD','GM','MD','PhD','MBA','CPA','RN','MD.','US','USA','UK','UAE','EMEA','APAC','LATAM','NA',
  'II','III','IV','SDR','BDR','AE','CSM','DevOps','API','ERP','CRM','SQL','AWS','GCP']);

const SMALL_WORDS = new Set(['of','and','the','for','in','on','at','to','a','an','or','&','de',
  'da','van','von','der','den','la','le','du','di','el','al','bin','ibn']);

function s(v){ return (v === null || v === undefined) ? '' : String(v).trim(); }
function blank(v){ return s(v) === '' || s(v).toLowerCase() === 'null'; }
function collapse(v){ return s(v).replace(/[\s ]+/g, ' ').trim(); }

// ---- EMAIL ----------------------------------------------------------------
const EMAIL_RE = /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/;

function cleanEmail(raw){
  const out = {clean:'', norm:'', domain:'', local:'', valid:false, flags:[]};
  let e = s(raw).toLowerCase().replace(/[\s​]/g,'').replace(/^mailto:/,'');
  e = e.replace(/^[<("']+/,'').replace(/[>)"'.,;]+$/,'');
  if (!e) return out;
  const at = e.lastIndexOf('@');
  if (at < 1 || at === e.length-1){ out.clean=e; out.flags.push('email_malformed'); return out; }
  let local = e.slice(0,at), domain = e.slice(at+1);
  if (domain.endsWith('.')) domain = domain.slice(0,-1);
  // common typo fixes on the TLD only (conservative)
  const TYPO = {'gmail.co':'gmail.com','gmial.com':'gmail.com','gmai.com':'gmail.com',
    'gmail.con':'gmail.com','hotmial.com':'hotmail.com','yahho.com':'yahoo.com',
    'outlok.com':'outlook.com','hotmail.con':'hotmail.com','yahoo.con':'yahoo.com'};
  if (TYPO[domain]){ out.flags.push('email_typo_fixed:'+domain); domain = TYPO[domain]; }
  out.clean  = local + '@' + domain;
  out.local  = local;
  out.domain = domain;
  out.valid  = EMAIL_RE.test(out.clean) && domain.includes('.');
  if (!out.valid) out.flags.push('email_invalid_syntax');
  // normalised form used ONLY for duplicate matching, never written back
  let nl = local;
  if (domain === 'gmail.com' || domain === 'googlemail.com'){
    nl = nl.split('+')[0].replace(/\./g,'');
  } else {
    nl = nl.split('+')[0];
  }
  out.norm = out.valid ? (nl + '@' + (domain === 'googlemail.com' ? 'gmail.com' : domain)) : '';
  const base = local.split('+')[0].replace(/[._-]/g,'');
  if (ROLE_LOCAL.has(local.split('+')[0]) || ROLE_LOCAL.has(base)) out.flags.push('role_address');
  if (DISPOSABLE.some(d => domain.includes(d))) out.flags.push('disposable_domain');
  if (FREE_MAIL.has(domain)) out.flags.push('free_mail_domain');
  if (/^(test|asdf|qwerty|aaa|xxx|abc|none|na|n\/a|noemail)/.test(local)) out.flags.push('email_looks_fake');
  return out;
}

// ---- PHONE ----------------------------------------------------------------
function cleanPhone(raw, defaultCountry){
  const out = {e164:'', clean:'', valid:false, flags:[]};
  let p = s(raw);
  if (!p) return out;
  const ext = p.match(/(?:ext|x|extension|#)\s*\.?\s*(\d{1,6})\s*$/i);
  if (ext){ out.ext = ext[1]; p = p.slice(0, ext.index); }
  let plus = /^\s*\+/.test(p) || /^\s*00\d/.test(p);
  let digits = p.replace(/\D/g,'');
  if (!digits){ out.flags.push('phone_no_digits'); return out; }
  if (/^00/.test(p.replace(/\D/g,'').slice(0,2)) && /^\s*00/.test(p.trim())){
    digits = digits.replace(/^00/,''); plus = true;
  }
  const cc = DIAL[s(defaultCountry).toUpperCase()] || '';
  if (!plus){
    // national format -> prepend the default country dial code
    if (cc === '1' && digits.length === 11 && digits.startsWith('1')) { /* already 1NXXXXXXXXX */ }
    else if (cc && digits.length <= 11){
      digits = digits.replace(/^0+/, '');            // strip national trunk prefix
      if (!digits.startsWith(cc)) digits = cc + digits;
    } else if (!cc){
      out.flags.push('phone_no_country_context');
    }
  }
  if (digits.length < 8 || digits.length > 15){
    out.flags.push('phone_invalid_length');
    out.clean = '+' + digits;
    return out;
  }
  if (/^(\d)\1+$/.test(digits) || /^(?:0123456789|1234567890)/.test(digits)){
    out.flags.push('phone_looks_fake');
  }
  out.e164  = '+' + digits;
  out.clean = out.e164;
  out.valid = out.flags.length === 0;
  return out;
}

// ---- NAMES / CASING -------------------------------------------------------
function titleCaseWord(w){
  if (!w) return w;
  const upper = w.toUpperCase().replace(/[^A-Z&./]/g,'');
  if (ACRONYMS.has(w.toUpperCase()) || ACRONYMS.has(upper)) return w.toUpperCase();
  if (/\d/.test(w)) return w;                                   // keep 3M, H2O, 24/7
  let t = w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
  t = t.replace(/^(mc)([a-z])/i,  (m,a,b)=> 'Mc' + b.toUpperCase());
  t = t.replace(/^(mac)([a-z]{2})/i,(m,a,b)=> 'Mac'+ b.charAt(0).toUpperCase()+b.slice(1));
  t = t.replace(/^(o')([a-z])/i,  (m,a,b)=> "O'" + b.toUpperCase());
  t = t.replace(/^(d')([a-z])/i,  (m,a,b)=> "d'" + b.toUpperCase());
  t = t.replace(/-([a-z])/g,      (m,b)  => '-'  + b.toUpperCase());
  return t;
}

function smartCase(raw, opts){
  const o = opts || {};
  let v = collapse(raw);
  if (!v) return '';
  const words = v.split(' ');
  // Re-case only when at least one word is clearly wrong (fully upper or fully
  // lower). Deliberate casing like "Jean-Luc Picard" or "DeShawn" is preserved.
  const anomalous = words.some(word => {
    const letters = word.replace(/[^A-Za-z]/g, '');
    if (letters.length < 2) return false;
    if (ACRONYMS.has(word.toUpperCase())) return false;
    return letters === letters.toUpperCase() || letters === letters.toLowerCase();
  });
  if (!o.force && !anomalous) return v;
  return words.map((w,i) => {
    const lw = w.toLowerCase();
    if (i > 0 && SMALL_WORDS.has(lw) && !o.keepSmall) return lw;
    return titleCaseWord(w);
  }).join(' ');
}

function cleanPersonName(raw){
  let v = collapse(raw).replace(/[",;]+/g,' ').replace(/\s+/g,' ').trim();
  v = v.replace(/^(mr|mrs|ms|miss|dr|prof|eng|sir)\.?\s+/i, '');
  if (!v) return {clean:'', flags:[]};
  const flags = [];
  if (/^[^A-Za-zÀ-ɏ؀-ۿ]+$/.test(v)) flags.push('name_not_alphabetic');
  if (/(test|asdf|qwerty|unknown|n\/a|none|xxx)/i.test(v) && v.length <= 8) flags.push('name_looks_fake');
  if (/https?:\/\/|www\.|@/.test(v)) flags.push('name_contains_url_or_email');
  return {clean: smartCase(v), flags};
}

// ---- COMPANY --------------------------------------------------------------
function normCompany(raw){
  let v = collapse(raw).toLowerCase();
  if (!v) return '';
  v = v.replace(/[‘’“”]/g,"'").replace(/&/g,' and ');
  v = v.replace(/[.,;:()\[\]\/\\'"`]/g,' ').replace(/\s+/g,' ').trim();
  let toks = v.split(' ').filter(Boolean);
  // Strip TRAILING legal forms only. Stripping them anywhere would turn
  // "Corporation Technologies Ltd" into "technologies".
  while (toks.length > 1 && LEGAL_SUFFIX.has(toks[toks.length-1])) toks.pop();
  return toks.join(' ').trim();
}

function cleanCompanyName(raw){
  const v = collapse(raw).replace(/[",;]+$/,'').trim();
  if (!v) return {clean:'', flags:[]};
  const flags = [];
  if (/^(unknown|n\/a|none|test|asdf|-{1,})$/i.test(v)) flags.push('company_looks_fake');
  return {clean: smartCase(v, {keepSmall:false}), flags};
}

function normDomain(raw){
  let d = s(raw).toLowerCase().trim();
  if (!d) return '';
  d = d.replace(/^https?:\/\//,'').replace(/^www\d?\./,'').split('/')[0].split('?')[0]
       .split('#')[0].split(':')[0].replace(/\.$/,'');
  if (!d.includes('.') || /\s/.test(d)) return '';
  return d;
}

// ---- GEO ------------------------------------------------------------------
function normCountry(raw){
  const v = collapse(raw);
  if (!v) return {clean:'', iso:'', flags:[]};
  const k = v.toLowerCase().replace(/\./g,'').trim();
  if (/^[A-Za-z]{2}$/.test(v) && Object.values(COUNTRY).includes(v.toUpperCase()))
    return {clean:v.toUpperCase(), iso:v.toUpperCase(), flags:[]};
  const iso = COUNTRY[k] || COUNTRY[k.replace(/^the /,'')] || '';
  if (!iso) return {clean:v, iso:'', flags:['country_unmapped']};
  return {clean:iso, iso, flags:[]};
}

function normState(raw, iso){
  const v = collapse(raw);
  if (!v) return {clean:'', flags:[]};
  if (iso !== 'US' && iso !== 'CA') return {clean:v, flags:[]};
  if (/^[A-Za-z]{2}$/.test(v)) return {clean:v.toUpperCase(), flags:[]};
  const code = US_STATE[v.toLowerCase()];
  return code ? {clean:code, flags:[]} : {clean:v, flags:['state_unmapped']};
}

// ---- SCORING --------------------------------------------------------------
function completeness(props, weights){
  let got = 0, total = 0;
  const missing = [];
  for (const [f, w] of Object.entries(weights)){
    total += w;
    if (!blank(props[f])) got += w; else missing.push(f);
  }
  return {score: total ? Math.round((got/total)*100) : 0, missing};
}

function pick(obj, keys){ const o = {}; for (const k of keys) if (k in obj) o[k] = obj[k]; return o; }
function uniq(a){ return Array.from(new Set(a.filter(Boolean))); }
function dayDiff(a, b){
  const x = Date.parse(a), y = Date.parse(b);
  if (isNaN(x) || isNaN(y)) return null;
  return Math.abs(x - y) / 86400000;
}
// ============================ END LIB =======================================

// ===========================================================================
//  NORMALISE & SCORE  —  computes a minimal diff per record, never a blind
//  overwrite. Only properties that actually change are sent to HubSpot.
// ===========================================================================
const spec = $('🔁 Next Page Cursor').first().json;
const cfg  = spec.config;
const type = spec.objectType;
const nowIso = new Date().toISOString();

const page = $input.all().map(i => i.json).filter(r => r && r.id);

const updates = [];          // { id, properties }
const details = [];          // per-record audit rows
let flaggedCount = 0, fieldsChanged = 0;
const byFix = {}, byFlag = {};
const bump = (o, k) => { o[k] = (o[k] || 0) + 1; };

for (const rec of page) {
  const p = rec.properties || {};
  const changes = {};
  const flags = [];
  const fixes = [];

  const setIf = (field, next, label) => {
    // Compare against the RAW stored value, not a trimmed copy — otherwise a
    // value that differs only by surrounding whitespace is never corrected.
    const cur = (p[field] === null || p[field] === undefined) ? '' : String(p[field]);
    if (next !== null && next !== undefined && String(next) !== cur && String(next) !== '') {
      changes[field] = String(next);
      fixes.push(label || field);
      bump(byFix, label || field);
    }
  };

  // ---------------------------------------------------------------- EMAIL --
  if (type === 'contacts') {
    const raw = s(p.email);
    if (raw) {
      const em = cleanEmail(raw);
      flags.push(...em.flags);
      // Only write LOSSLESS corrections (trim / case / mailto: / stray quotes).
      // A guessed domain typo is flagged for a human, never silently applied.
      const lossless = em.clean && em.clean !== raw &&
        em.clean === raw.trim().toLowerCase().replace(/^mailto:/, '').replace(/[<>()"' ]/g, '') &&
        !em.flags.some(f => f.startsWith('email_typo_fixed'));
      if (lossless) setIf('email', em.clean, 'email_case_trim');
      if (em.flags.some(f => f.startsWith('email_typo_fixed'))) {
        flags.push('email_typo_suspected:' + em.clean);
      }
    } else {
      flags.push('email_missing');
    }
  }

  // ---------------------------------------------------------------- PHONE --
  if (type === 'contacts' || type === 'companies') {
    const country = normCountry(p.country).iso || cfg.defaultCountry;
    for (const f of (type === 'contacts' ? ['phone', 'mobilephone'] : ['phone'])) {
      const raw = s(p[f]);
      if (!raw) continue;
      const ph = cleanPhone(raw, country);
      if (ph.e164) setIf(f, ph.e164, f + '_e164');
      else flags.push(...ph.flags.map(x => `${f}:${x}`));
      if (ph.ext) flags.push(`${f}_had_extension:${ph.ext}`);
    }
  }

  // ------------------------------------------------------- NAMES / CASING --
  if (type === 'contacts') {
    for (const f of ['firstname', 'lastname']) {
      const raw = s(p[f]);
      if (!raw) { flags.push(f + '_missing'); continue; }
      const n = cleanPersonName(raw);
      flags.push(...n.flags.map(x => `${f}:${x}`));
      setIf(f, n.clean, f + '_casing');
    }
    if (s(p.company)) setIf('company', cleanCompanyName(p.company).clean, 'company_casing');
    if (s(p.jobtitle)) setIf('jobtitle', smartCase(p.jobtitle), 'jobtitle_casing');
  }

  if (type === 'companies') {
    const cn = cleanCompanyName(p.name);
    flags.push(...cn.flags);
    setIf('name', cn.clean, 'company_name_casing');
    const d = normDomain(p.domain || p.website);
    if (d) setIf('domain', d, 'domain_normalised'); else flags.push('domain_missing_or_invalid');
    if (s(p.website)) {
      const wd = normDomain(p.website);
      if (wd) setIf('website', 'https://' + wd, 'website_normalised');
    }
    const emp = s(p.numberofemployees).replace(/[^\d]/g, '');
    if (s(p.numberofemployees) && emp) setIf('numberofemployees', emp, 'employees_numeric');
  }

  if (type === 'deals') {
    const dn = collapse(p.dealname);
    if (!dn) flags.push('dealname_missing');
    else setIf('dealname', smartCase(dn), 'dealname_casing');
    const amtRaw = s(p.amount);
    if (amtRaw) {
      const amt = amtRaw.replace(/[^0-9.\-]/g, '');
      if (amt && amt !== amtRaw) setIf('amount', amt, 'amount_numeric');
      if (Number(amt) <= 0) flags.push('amount_zero_or_negative');
    } else flags.push('amount_missing');
    if (!s(p.closedate)) flags.push('closedate_missing');
    else if (isNaN(Date.parse(p.closedate))) flags.push('closedate_unparseable');
  }

  // ------------------------------------------------------------------ GEO --
  if (type === 'contacts' || type === 'companies') {
    const c = normCountry(p.country);
    if (s(p.country)) { flags.push(...c.flags); setIf('country', c.clean, 'country_iso2'); }
    const st = normState(p.state, c.iso || cfg.defaultCountry);
    if (s(p.state)) { flags.push(...st.flags); setIf('state', st.clean, 'state_code'); }
    if (s(p.city)) setIf('city', smartCase(p.city), 'city_casing');
    if (s(p.zip)) setIf('zip', collapse(p.zip).toUpperCase(), 'zip_normalised');
  }

  // --------------------------------------------------------- COMPLETENESS --
  const merged = { ...p, ...changes };
  const comp = completeness(merged, spec.weights);
  for (const m of comp.missing) flags.push('missing:' + m);

  const uniqueFlags = uniq(flags);
  for (const f of uniqueFlags) bump(byFlag, f.split(':')[0]);
  if (uniqueFlags.length) flaggedCount++;

  // ------------------------------------------------- audit property stamps --
  if (cfg.writeHygieneProps) {
    const flagStr = uniqueFlags.join('; ').slice(0, 900);
    if (String(comp.score) !== s(p.hygiene_score)) changes.hygiene_score = String(comp.score);
    if (flagStr !== s(p.hygiene_flags))            changes.hygiene_flags = flagStr;
    changes.hygiene_last_run = nowIso;
  }

  const realFixes = fixes.length;
  fieldsChanged += realFixes;

  details.push({ id: rec.id, fixes, flags: uniqueFlags, score: comp.score,
                 changed: Object.keys(changes) });

  // A record with only the `hygiene_last_run` stamp is not worth an API write.
  const meaningful = Object.keys(changes).filter(k => k !== 'hygiene_last_run');
  if (meaningful.length) updates.push({ id: rec.id, properties: changes });
}

// ---- chunk into HubSpot batch-update payloads (hard limit: 100 per call) ---
const CHUNK = 100;
const batches = [];
for (let i = 0; i < updates.length; i += CHUNK) {
  batches.push({ inputs: updates.slice(i, i + CHUNK) });
}

const pageStats = {
  scanned: page.length,
  recordsUpdated: updates.length,
  fieldsChanged,
  recordsFlagged: flaggedCount,
  byFix, byFlag,
};

// ALWAYS emit at least one item so the loop that follows never starves.
if (!batches.length) {
  return [{ json: { batchIndex: 0, batchCount: 0, skip: true, reason: 'no changes on this page',
                    inputs: [], pageStats, details, dryRun: cfg.dryRun } }];
}
return batches.map((b, i) => ({
  json: { batchIndex: i + 1, batchCount: batches.length, skip: cfg.dryRun,
          reason: cfg.dryRun ? 'dry run' : '', inputs: b.inputs,
          pageStats: i === 0 ? pageStats : null, details: i === 0 ? details : [],
          dryRun: cfg.dryRun },
}));

// HubSpot rejects a whole batch on some errors (e.g. 409 duplicate email).
// Record it, keep going — the digest surfaces the count and the reason.
const e = $input.first().json || {};
const msg = String(e.error?.message || e.message || JSON.stringify(e)).slice(0, 600);
const batch = $('🔁 Write Batches').first().json;
return [{ json: { writeError: true, batchIndex: batch.batchIndex,
                  affectedIds: (batch.inputs || []).map(x => x.id),
                  count: (batch.inputs || []).length, message: msg } }];

// Runs once per page, after every write batch for that page has settled.
const spec  = $('🔁 Next Page Cursor').first().json;
const fetch = $('HubSpot: Search Page').first().json || {};
const batchItems = $('🧼 Normalize, Diff & Score').all().map(i => i.json);
const ps = batchItems.find(b => b.pageStats)?.pageStats
        || { scanned:0, recordsUpdated:0, fieldsChanged:0, recordsFlagged:0, byFix:{}, byFlag:{} };

// Count batches that failed to write, if any.
let writeErrors = 0, errorSamples = [];
try {
  for (const it of $('🩹 Capture Write Errors').all()) {
    if (it.json?.writeError) { writeErrors += it.json.count || 1; errorSamples.push(it.json.message); }
  }
} catch (e) { /* node never executed on this page */ }

const prev = spec.stats || {};
const addMap = (a, b) => { const o = { ...(a || {}) }; for (const [k, v] of Object.entries(b || {})) o[k] = (o[k] || 0) + v; return o; };

const stats = {
  scanned:        (prev.scanned || 0)        + ps.scanned,
  recordsUpdated: (prev.recordsUpdated || 0) + (spec.config.dryRun ? 0 : ps.recordsUpdated),
  wouldUpdate:    (prev.wouldUpdate || 0)    + ps.recordsUpdated,
  fieldsChanged:  (prev.fieldsChanged || 0)  + ps.fieldsChanged,
  recordsFlagged: (prev.recordsFlagged || 0) + ps.recordsFlagged,
  writeErrors:    (prev.writeErrors || 0)    + writeErrors,
  pages:          (prev.pages || 0) + 1,
  byFix:  addMap(prev.byFix,  ps.byFix),
  byFlag: addMap(prev.byFlag, ps.byFlag),
  errorSamples: [...(prev.errorSamples || []), ...errorSamples].slice(0, 5),
};

const nextAfter = fetch.paging?.next?.after || null;
return [{ json: { ...spec, stats, pageNo: spec.pageNo, nextAfter,
                  hasMore: Boolean(nextAfter) } }];

const j = $input.first().json || {};
const spec = $('⚙️ Resolve Job Config').first().json;
const stats = j.stats || spec.stats || {};

const topN = (obj, n) => Object.entries(obj || {}).sort((a, b) => b[1] - a[1]).slice(0, n)
  .map(([k, v]) => `${k}:${v}`);

return [{ json: {
  ok: true,
  runId: spec.runId,
  kind: 'hygiene',
  objectType: spec.objectType,
  summary: {
    scanned:        stats.scanned || 0,
    recordsUpdated: stats.recordsUpdated || 0,
    wouldUpdate:    stats.wouldUpdate || 0,
    fieldsChanged:  stats.fieldsChanged || 0,
    recordsFlagged: stats.recordsFlagged || 0,
    writeErrors:    stats.writeErrors || 0,
    pages:          stats.pages || 0,
    dryRun:         spec.config.dryRun,
    pageCapHit:     (stats.pages || 0) >= spec.config.maxPagesPerRun,
    aborted:        Boolean(j.aborted),
    abortReason:    j.abortReason || null,
    topFixes:       topN(stats.byFix, 8),
    topFlags:       topN(stats.byFlag, 8),
    errorSamples:   stats.errorSamples || [],
  },
} }];
